Looking at the `URLHandler` class, I'll apply several refactorings to improve code quality:

1. **Extract Method**: The repeated `self.url.find("://")` and slicing logic can be extracted into helper methods.
2. **Replace Temp with Query**: Temporary variables like `scheme_end`, `url_without_scheme`, `host_end` can be replaced with queries where appropriate.
3. **Decompose Conditional**: The nested conditionals in `get_host`, `get_path`, and `get_query_params` can be simplified with guard clauses.
4. **Replace Nested Conditional with Guard Clauses**: To reduce nesting in `get_host`, `get_path`, and `get_query_params`.
5. **Introduce Explaining Variable**: For magic numbers like `3` (length of "://").
6. **Remove Control Flag** / **Consolidate Duplicate Conditional Fragments**: The repeated finding of `://` can be consolidated.
7. **Encapsulate Field**: The `url` field is already encapsulated, but we can add a private attribute and property if desired. However, since it's simple string data, we'll keep it as is but use consistent access patterns.
8. **Replace Magic Number with Symbolic Constant**: The number `3` used for `"://"` length.

```python
class URLHandler:
    SCHEME_DELIMITER = "://"
    SCHEME_DELIMITER_LEN = len(SCHEME_DELIMITER)

    def __init__(self, url):
        self._url = url

    @property
    def url(self):
        return self._url

    @url.setter
    def url(self, value):
        self._url = value

    def _find_scheme_end(self):
        return self.url.find(self.SCHEME_DELIMITER)

    def _get_url_without_scheme(self):
        scheme_end = self._find_scheme_end()
        if scheme_end == -1:
            return None
        return self.url[scheme_end + self.SCHEME_DELIMITER_LEN:]

    def _get_host_port_part(self):
        url_without_scheme = self._get_url_without_scheme()
        if url_without_scheme is None:
            return None
        host_end = url_without_scheme.find("/")
        if host_end == -1:
            return url_without_scheme
        return url_without_scheme[:host_end]

    def _get_path_part(self):
        url_without_scheme = self._get_url_without_scheme()
        if url_without_scheme is None:
            return None
        host_end = url_without_scheme.find("/")
        if host_end == -1:
            return None
        return url_without_scheme[host_end:]

    def get_scheme(self):
        scheme_end = self._find_scheme_end()
        if scheme_end == -1:
            return None
        return self.url[:scheme_end]

    def get_host(self):
        return self._get_host_port_part()

    def get_path(self):
        return self._get_path_part()

    def get_query_params(self):
        query_start = self.url.find("?")
        if query_start == -1:
            return None

        fragment_start = self.url.find("#")
        if fragment_start != -1:
            query_string = self.url[query_start + 1:fragment_start]
        else:
            query_string = self.url[query_start + 1:]

        params = {}
        if len(query_string) == 0:
            return params

        param_pairs = query_string.split("&")
        for pair in param_pairs:
            key_value = pair.split("=", 1)
            if len(key_value) == 2:
                params[key_value[0]] = key_value[1]

        return params

    def get_fragment(self):
        fragment_start = self.url.find("#")
        if fragment_start == -1:
            return None
        return self.url[fragment_start + 1:]
